[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Leap Studio — Your Reinvention and Experience Partner</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

        :root {
            --bg-primary: #0A0A0A;
            --bg-secondary: #111111;
            --bg-tertiary: #1A1A1A;
            --text-primary: #FFFFFF;
            --text-secondary: #A0A0A0;
            --text-muted: #666666;
            --accent: #3B8BFF;
            --accent-warm: #FFB547;
            --border: rgba(255,255,255,0.08);
            --card-bg: #141414;
            --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
        }

        html { scroll-behavior: smooth; }

        body {
            font-family: var(--font-family);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.6;
            overflow-x: hidden;
        }

        /* Navigation */
        .nav {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 100;
            background: rgba(10,10,10,0.85);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border-bottom: 1px solid var(--border);
        }

        .nav-inner {
            max-width: 1440px;
            margin: 0 auto;
            padding: 0 48px;
            height: 72px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .nav-logo {
            font-size: 20px;
            font-weight: 700;
            letter-spacing: -0.5px;
            color: var(--text-primary);
            text-decoration: none;
        }

        .nav-links {
            display: flex;
            gap: 40px;
            list-style: none;
        }

        .nav-links a {
            color: var(--text-secondary);
            text-decoration: none;
            font-size: 14px;
            font-weight: 500;
            transition: color 0.2s ease;
            cursor: pointer;
        }

        .nav-links a:hover { color: var(--text-primary); }

        .nav-right {
            display: flex;
            align-items: center;
            gap: 24px;
        }

        .lang-selector {
            position: relative;
        }

        .lang-btn {
            display: flex;
            align-items: center;
            gap: 6px;
            background: transparent;
            border: 1px solid var(--border);
            color: var(--text-secondary);
            padding: 8px 14px;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .lang-btn:hover {
            border-color: var(--text-secondary);
            color: var(--text-primary);
        }

        .lang-btn svg { width: 16px; height: 16px; }

        .lang-dropdown {
            position: absolute;
            top: calc(100% + 8px);
            right: 0;
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 8px;
            min-width: 160px;
            opacity: 0;
            visibility: hidden;
            transform: translateY(-8px);
            transition: all 0.2s ease;
        }

        .lang-dropdown.active {
            opacity: 1;
            visibility: visible;
            transform: translateY(0);
        }

        .lang-option {
            display: block;
            width: 100%;
            padding: 10px 14px;
            background: transparent;
            border: none;
            color: var(--text-secondary);
            font-size: 14px;
            text-align: left;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.15s ease;
        }

        .lang-option:hover {
            background: var(--bg-tertiary);
            color: var(--text-primary);
        }

        .mobile-menu-btn {
            display: none;
            background: transparent;
            border: none;
            color: var(--text-primary);
            cursor: pointer;
            padding: 8px;
        }

        /* Hero Section */
        .hero {
            min-height: 100vh;
            display: flex;
            align-items: center;
            padding: 120px 48px 80px;
            position: relative;
        }

        .hero-inner {
            max-width: 1440px;
            margin: 0 auto;
            width: 100%;
        }

        .hero-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: rgba(59,139,255,0.1);
            border: 1px solid rgba(59,139,255,0.3);
            color: var(--accent);
            padding: 8px 16px;
            border-radius: 100px;
            font-size: 13px;
            font-weight: 500;
            margin-bottom: 32px;
        }

        .hero-badge::before {
            content: '';
            width: 8px;
            height: 8px;
            background: var(--accent);
            border-radius: 50%;
            animation: pulse 2s infinite;
        }

        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.4; }
        }

        .hero h1 {
            font-size: clamp(40px, 7vw, 80px);
            font-weight: 800;
            line-height: 1.05;
            letter-spacing: -2px;
            margin-bottom: 24px;
            max-width: 900px;
        }

        .hero-subtitle {
            font-size: 18px;
            color: var(--text-secondary);
            max-width: 540px;
            margin-bottom: 48px;
            line-height: 1.7;
        }

        /* Hero Carousel */
        .hero-carousel {
            position: relative;
            margin-top: 60px;
        }

        .hero-slides {
            display: flex;
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .hero-slide {
            flex: 0 0 100%;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 48px;
            min-height: 400px;
        }

        .hero-slide-content {
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .hero-slide-tag {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            color: var(--accent-warm);
            margin-bottom: 16px;
        }

        .hero-slide h2 {
            font-size: clamp(28px, 3vw, 40px);
            font-weight: 700;
            line-height: 1.2;
            letter-spacing: -0.5px;
            margin-bottom: 16px;
        }

        .hero-slide p {
            font-size: 16px;
            color: var(--text-secondary);
            line-height: 1.7;
            margin-bottom: 32px;
        }

        .hero-cta {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: var(--text-primary);
            color: var(--bg-primary);
            padding: 14px 28px;
            border-radius: 100px;
            font-size: 14px;
            font-weight: 600;
            text-decoration: none;
            transition: all 0.2s ease;
            cursor: pointer;
            border: none;
            align-self: flex-start;
        }

        .hero-cta:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(255,255,255,0.15);
        }

        .hero-slide-image {
            border-radius: 20px;
            overflow: hidden;
            background: var(--bg-tertiary);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .hero-slide-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .hero-slide-placeholder {
            width: 100%;
            height: 100%;
            background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--card-bg) 100%);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .hero-slide-placeholder svg {
            width: 80px;
            height: 80px;
            opacity: 0.3;
        }

        .hero-nav {
            display: flex;
            align-items: center;
            gap: 16px;
            margin-top: 40px;
        }

        .hero-dots {
            display: flex;
            gap: 8px;
        }

        .hero-dot {
            width: 32px;
            height: 4px;
            background: var(--bg-tertiary);
            border-radius: 2px;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .hero-dot.active {
            background: var(--text-primary);
            width: 48px;
        }

        .hero-arrow {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 48px;
            height: 48px;
            border: 1px solid var(--border);
            border-radius: 50%;
            background: transparent;
            color: var(--text-secondary);
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .hero-arrow:hover {
            border-color: var(--text-primary);
            color: var(--text-primary);
        }

        .hero-arrow:disabled {
            opacity: 0.3;
            cursor: not-allowed;
        }

        /* Section Common */
        section {
            padding: 100px 48px;
        }

        .section-inner {
            max-width: 1440px;
            margin: 0 auto;
        }

        .section-header {
            margin-bottom: 64px;
        }

        .section-label {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            color: var(--accent);
            margin-bottom: 16px;
        }

        .section-title {
            font-size: clamp(32px, 4vw, 48px);
            font-weight: 700;
            letter-spacing: -1px;
            line-height: 1.1;
            margin-bottom: 16px;
        }

        .section-subtitle {
            font-size: 18px;
            color: var(--text-secondary);
            max-width: 600px;
            line-height: 1.7;
        }

        /* Team Carousel */
        .team-section {
            background: var(--bg-secondary);
        }

        .region-tabs {
            display: flex;
            gap: 8px;
            margin-bottom: 48px;
            flex-wrap: wrap;
        }

        .region-tab {
            padding: 12px 24px;
            background: transparent;
            border: 1px solid var(--border);
            border-radius: 100px;
            color: var(--text-secondary);
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .region-tab:hover {
            border-color: var(--text-secondary);
            color: var(--text-primary);
        }

        .region-tab.active {
            background: var(--text-primary);
            border-color: var(--text-primary);
            color: var(--bg-primary);
        }

        .team-carousel-wrapper {
            position: relative;
            overflow: hidden;
        }

        .team-carousel {
            display: flex;
            gap: 24px;
            transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .team-card {
            flex: 0 0 calc(33.333% - 16px);
            min-width: 320px;
            background: var(--bg-tertiary);
            border-radius: 20px;
            overflow: hidden;
            border: 1px solid var(--border);
        }

        .team-card-image {
            height: 280px;
            background: linear-gradient(135deg, #1a1a1a 0%, #0d0d0d 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            overflow: hidden;
        }

        .team-card-image::before {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(180deg, transparent 50%, rgba(10,10,10,0.8) 100%);
        }

        .team-avatar {
            width: 100px;
            height: 100px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--accent) 0%, #1a5dc9 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 36px;
            font-weight: 600;
            color: white;
        }

        .team-card-content {
            padding: 28px;
        }

        .team-card-quote {
            font-size: 15px;
            font-style: italic;
            color: var(--text-secondary);
            line-height: 1.7;
            margin-bottom: 24px;
            position: relative;
            padding-left: 20px;
        }

        .team-card-quote::before {
            content: '"';
            position: absolute;
            left: 0;
            top: -4px;
            font-size: 32px;
            color: var(--accent);
            font-family: Georgia, serif;
        }

        .team-card-info h4 {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 4px;
        }

        .team-card-info p {
            font-size: 14px;
            color: var(--text-muted);
            margin-bottom: 16px;
        }

        .team-card-cta {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            color: var(--accent);
            font-size: 14px;
            font-weight: 500;
            text-decoration: none;
            transition: gap 0.2s ease;
            cursor: pointer;
        }

        .team-card-cta:hover { gap: 10px; }

        .team-carousel-nav {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-top: 40px;
        }

        .team-nav-btn {
            width: 44px;
            height: 44px;
            border-radius: 50%;
            border: 1px solid var(--border);
            background: transparent;
            color: var(--text-secondary);
            cursor: pointer;
            transition: all 0.2s ease;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .team-nav-btn:hover:not(:disabled) {
            border-color: var(--text-primary);
            color: var(--text-primary);
        }

        .team-nav-btn:disabled {
            opacity: 0.3;
            cursor: not-allowed;
        }

        .team-counter {
            font-size: 14px;
            color: var(--text-muted);
        }

        /* Work Showcase */
        .work-section {
            overflow: hidden;
        }

        .work-carousel-wrapper {
            position: relative;
            margin: 0 -48px;
            padding: 0 48px;
        }

        .work-carousel {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            scroll-snap-type: x mandatory;
            scrollbar-width: none;
            -ms-overflow-style: none;
            padding-bottom: 20px;
        }

        .work-carousel::-webkit-scrollbar { display: none; }

        .work-card {
            flex: 0 0 400px;
            scroll-snap-align: start;
            background: var(--card-bg);
            border-radius: 20px;
            overflow: hidden;
            border: 1px solid var(--border);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .work-card:hover {
            transform: translateY(-8px);
            box-shadow: 0 20px 60px rgba(0,0,0,0.4);
        }

        .work-card-image {
            height: 260px;
            background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--card-bg) 100%);
            position: relative;
            overflow: hidden;
        }

        .work-card-image::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 80px;
            background: linear-gradient(transparent, var(--card-bg));
        }

        .work-card-content {
            padding: 28px;
        }

        .work-card-client {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--accent);
            margin-bottom: 12px;
        }

        .work-card-title {
            font-size: 20px;
            font-weight: 600;
            margin-bottom: 12px;
            line-height: 1.3;
        }

        .work-card-desc {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        .work-card-quote {
            margin-top: 20px;
            padding-top: 20px;
            border-top: 1px solid var(--border);
            font-size: 14px;
            color: var(--text-muted);
            font-style: italic;
        }

        .work-card-quote cite {
            display: block;
            margin-top: 8px;
            font-style: normal;
            color: var(--text-secondary);
            font-size: 13px;
        }

        /* CTA Banner */
        .cta-banner {
            background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-secondary) 100%);
            border-top: 1px solid var(--border);
            border-bottom: 1px solid var(--border);
        }

        .cta-banner-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 48px;
        }

        .cta-banner-content h2 {
            font-size: clamp(28px, 3vw, 40px);
            font-weight: 700;
            letter-spacing: -0.5px;
            margin-bottom: 12px;
        }

        .cta-banner-content p {
            font-size: 16px;
            color: var(--text-secondary);
            max-width: 500px;
        }

        .cta-banner .hero-cta {
            flex-shrink: 0;
        }

        /* How We Work */
        .how-section {
            background: var(--bg-primary);
        }

        .how-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            align-items: center;
        }

        .how-content h2 {
            font-size: clamp(32px, 4vw, 48px);
            font-weight: 700;
            letter-spacing: -1px;
            line-height: 1.1;
            margin-bottom: 24px;
        }

        .how-content p {
            font-size: 17px;
            color: var(--text-secondary);
            line-height: 1.8;
            margin-bottom: 32px;
        }

        .how-image {
            border-radius: 20px;
            overflow: hidden;
            aspect-ratio: 4/3;
            background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--card-bg) 100%);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* Latest Insights */
        .insights-section {
            background: var(--bg-secondary);
        }

        .insights-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
        }

        .insight-card {
            background: var(--bg-tertiary);
            border-radius: 16px;
            overflow: hidden;
            border: 1px solid var(--border);
            transition: transform 0.2s ease;
        }

        .insight-card:hover { transform: translateY(-4px); }

        .insight-card.featured {
            grid-column: span 2;
            grid-row: span 2;
        }

        .insight-image {
            height: 180px;
            background: linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-tertiary) 100%);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .insight-card.featured .insight-image { height: 300px; }

        .insight-type {
            position: absolute;
            top: 16px;
            left: 16px;
            background: rgba(0,0,0,0.7);
            backdrop-filter: blur(8px);
            padding: 6px 12px;
            border-radius: 6px;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .insight-content {
            padding: 20px;
        }

        .insight-card h3 {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 8px;
            line-height: 1.4;
        }

        .insight-card.featured h3 {
            font-size: 24px;
        }

        .insight-link {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            color: var(--accent);
            font-size: 14px;
            font-weight: 500;
            margin-top: 16px;
            text-decoration: none;
            cursor: pointer;
            transition: gap 0.2s ease;
        }

        .insight-link:hover { gap: 10px; }

        /* Principles */
        .principles-section {
            background: var(--bg-primary);
        }

        .principles-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 32px;
        }

        .principle-card {
            background: var(--card-bg);
            border: 1px solid var(--border);
            border-radius: 20px;
            padding: 40px;
            transition: border-color 0.2s ease;
        }

        .principle-card:hover { border-color: var(--text-muted); }

        .principle-number {
            font-size: 14px;
            font-weight: 600;
            color: var(--accent);
            margin-bottom: 20px;
        }

        .principle-card h3 {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 16px;
        }

        .principle-card p {
            font-size: 16px;
            color: var(--text-secondary);
            line-height: 1.7;
        }

        /* Footer */
        footer {
            background: var(--bg-secondary);
            border-top: 1px solid var(--border);
            padding: 80px 48px 40px;
        }

        .footer-inner { max-width: 1440px; margin: 0 auto; }

        .footer-cta-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 48px;
            padding-bottom: 64px;
            border-bottom: 1px solid var(--border);
            margin-bottom: 48px;
        }

        .footer-cta h3 {
            font-size: 28px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .footer-cta p {
            font-size: 15px;
            color: var(--text-secondary);
            margin-bottom: 20px;
        }

        .footer-links {
            display: flex;
            justify-content: space-between;
            margin-bottom: 48px;
        }

        .footer-links-col h4 {
            font-size: 14px;
            font-weight: 600;
            margin-bottom: 20px;
            color: var(--text-primary);
        }

        .footer-links-col ul {
            list-style: none;
        }

        .footer-links-col li { margin-bottom: 12px; }

        .footer-links-col a {
            color: var(--text-secondary);
            text-decoration: none;
            font-size: 14px;
            transition: color 0.2s ease;
        }

        .footer-links-col a:hover { color: var(--text-primary); }

        .footer-legal {
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 13px;
            color: var(--text-muted);
        }

        .footer-legal-links {
            display: flex;
            gap: 24px;
        }

        .footer-legal-links a {
            color: var(--text-muted);
            text-decoration: none;
            transition: color 0.2s ease;
            cursor: pointer;
        }

        .footer-legal-links a:hover { color: var(--text-secondary); }

        /* Cookie Banner */
        .cookie-banner {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background: var(--bg-secondary);
            border-top: 1px solid var(--border);
            padding: 24px 48px;
            z-index: 200;
            transform: translateY(100%);
            transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .cookie-banner.active { transform: translateY(0); }

        .cookie-inner {
            max-width: 1440px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 32px;
        }

        .cookie-text {
            font-size: 14px;
            color: var(--text-secondary);
        }

        .cookie-text a {
            color: var(--text-primary);
            cursor: pointer;
        }

        .cookie-actions {
            display: flex;
            gap: 12px;
        }

        .cookie-btn {
            padding: 12px 24px;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
            border: none;
        }

        .cookie-btn.primary {
            background: var(--text-primary);
            color: var(--bg-primary);
        }

        .cookie-btn.primary:hover { opacity: 0.9; }

        .cookie-btn.secondary {
            background: transparent;
            border: 1px solid var(--border);
            color: var(--text-secondary);
        }

        .cookie-btn.secondary:hover {
            border-color: var(--text-secondary);
            color: var(--text-primary);
        }

        /* Mobile Menu */
        .mobile-nav {
            display: none;
            position: fixed;
            top: 72px;
            left: 0;
            right: 0;
            bottom: 0;
            background: var(--bg-primary);
            z-index: 99;
            padding: 24px;
            transform: translateY(-100%);
            transition: transform 0.3s ease;
        }

        .mobile-nav.active { transform: translateY(0); }

        .mobile-nav-links {
            list-style: none;
        }

        .mobile-nav-links li { margin-bottom: 16px; }

        .mobile-nav-links a {
            font-size: 24px;
            font-weight: 500;
            color: var(--text-primary);
            text-decoration: none;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            section { padding: 80px 32px; }
            .nav-inner { padding: 0 32px; }
            .hero-slide { grid-template-columns: 1fr; }
            .hero-slide-image { display: none; }
            .team-card { flex: 0 0 calc(50% - 12px); }
            .insights-grid { grid-template-columns: repeat(2, 1fr); }
            .insight-card.featured { grid-column: span 2; }
            .how-grid { gap: 48px; }
        }

        @media (max-width: 768px) {
            .nav-links { display: none; }
            .mobile-menu-btn { display: block; }
            .mobile-nav { display: block; }
            section { padding: 64px 20px; }
            .hero { padding: 100px 20px 60px; }
            .hero h1 { font-size: 36px; letter-spacing: -1px; }
            .section-title { font-size: 28px; }
            .team-card { flex: 0 0 100%; min-width: auto; }
            .work-card { flex: 0 0 320px; }
            .cta-banner-inner { flex-direction: column; text-align: center; }
            .how-grid { grid-template-columns: 1fr; }
            .principles-grid { grid-template-columns: 1fr; }
            .footer-cta-row { grid-template-columns: 1fr; }
            .footer-links { flex-direction: column; gap: 32px; }
            .footer-legal { flex-direction: column; gap: 16px; text-align: center; }
            .cookie-inner { flex-direction: column; text-align: center; }
            .insights-grid { grid-template-columns: 1fr; }
            .insight-card.featured { grid-column: span 1; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.01ms !important;
            }
        }
    </style>
